"""Conversations that happened before the run, generated by the actors in them.

A scenario states the situation of each session (who, where, about what); the actors write the messages. Each turn,
every actor of the session in order is asked from its own brief and the thread so far whether it writes now, and
what; an actor may pass, and a line it already wrote counts as a pass. The session ends when a whole round passes
with no one writing, or at `max_messages` (20 unless set). The
thread is stored with the scenario, with the fingerprint of what it was generated from, and replayed before every
trial; a session whose fingerprint no longer matches is written again before sealing.

`where` names the place: `{"action": "slack.post", "arguments": {"channel": "#leads"}}`, and, for a place with
replies, `"reply": {"action": "slack.reply", "argument": "thread_ts", "field": "ts"}`: a message that answers an
earlier one is sent with that action, its `argument` filled at replay from the earlier message's result `field`.
"""

from __future__ import annotations

import inspect
import json
from collections.abc import Callable
from typing import Any

from fi.simulate.simulation.call_actors import LIMIT_DEFAULTS

from .actors import Actor, PreRunSession, Reference, ThreadMessage, session_fingerprint

# What an actor is asked each turn of a pre-run session.
SESSION_ASK = (
    'Reply with JSON only: {"text": "<your message, in your own words>", "reply_to": <the number of the message '
    'you answer, or null>} to write now, or {"text": null} to pass. Write only what you would write here.'
)

Write = Callable[[str, Actor], Any]


def problems(
    session: PreRunSession, number: int, listed: dict[str, Actor]
) -> list[str]:
    """Why a session cannot be written or replayed, or nothing: every actor listed and permitted to write where the
    session is, every message by a listed actor using an action it may take, every reference to an earlier one."""
    out = []
    label = f"pre_run {number}"
    action = str((session.where or {}).get("action") or "")
    reply = (session.where or {}).get("reply") or {}
    if not session.actors and not session.thread:
        out.append(f"{label}: name the actors who were in this conversation")
    for actor_id in session.actors:
        actor = listed.get(actor_id)
        if actor is None:
            out.append(
                f"{label}: {actor_id!r} is not an actor; add it with add_actor first"
            )
        elif action and action not in actor.permitted_actions:
            out.append(
                f"{label}: {actor_id} may not {action}, so it cannot write in this place; it may "
                + (", ".join(actor.permitted_actions) or "do nothing in the world")
            )
    if session.thread == [] and not action:
        # Said with the shape and the actions these actors could write with, so the next submission can be right.
        writes = sorted(
            {one for actor_id in session.actors if (actor := listed.get(actor_id)) for one in actor.permitted_actions}
        )
        out.append(
            f"{label}: `where` needs `action`, the world action that writes into this place, beside the arguments "
            'naming the place, such as {"action": "chat.post_message", "arguments": {"channel": "#sales"}}'
            + (f"; these actors may write with {', '.join(writes)}" if writes else "")
        )
    for position, message in enumerate(session.thread, start=1):
        actor = listed.get(message.actor)
        if actor is None:
            out.append(f"{label} message {position}: {message.actor!r} is not an actor")
            continue
        if message.action not in actor.permitted_actions:
            out.append(
                f"{label} message {position}: {message.actor} may not {message.action}"
            )
        for name, ref in message.refers.items():
            if ref.message >= position:
                out.append(
                    f"{label} message {position}: `{name}` refers to a message that is not before it"
                )
    if (
        reply
        and reply.get("action")
        and any(
            reply["action"] not in listed[one].permitted_actions
            for one in session.actors
            if one in listed
        )
    ):
        out.append(
            f"{label}: every actor in it needs {reply['action']} to reply in this place"
        )
    return out


def session_problems(raw: Any, root: Any) -> list[str]:
    """Why a scenario's pre-run sessions, as written, cannot be generated or replayed; nothing when they can."""
    from pathlib import Path

    from .actors import load_actors

    listed = load_actors(Path(root)).by_id()
    out = []
    for number, one in enumerate(raw if isinstance(raw, list) else [], start=1):
        try:
            session = PreRunSession.model_validate(one)
        except Exception as invalid:  # noqa: BLE001 - said back to the writer as the fix
            out.append(f"pre_run {number}: {str(invalid)[:200]}")
            continue
        out += problems(session, number, listed)
    return out


def _brief(
    actor: Actor, brief: str, session: PreRunSession, thread: list[ThreadMessage]
) -> str:
    said = "\n".join(
        f"{number}. {message.actor}: {message.arguments.get('text', json.dumps(message.arguments, default=str))}"
        for number, message in enumerate(thread, start=1)
    )
    return "\n\n".join(
        [
            brief or f"You are {actor.name}.",
            f"Where you are writing: {json.dumps(session.where.get('arguments') or {}, default=str)}",
            f"What this conversation is about (it happened before anything else): {session.about}",
            "The conversation so far, oldest first:\n" + (said or "nothing yet"),
            SESSION_ASK,
        ]
    )


def _read(raw: Any) -> dict[str, Any] | None:
    text = str(raw or "").strip()
    start, end = text.find("{"), text.rfind("}")
    if start < 0 or end <= start:
        return {"text": text} if text else None
    try:
        parsed = json.loads(text[start : end + 1])
    except ValueError:
        return None
    return parsed if isinstance(parsed, dict) else None


def _repeats(actor: str, text: str, thread: list[ThreadMessage]) -> bool:
    """Whether this actor already wrote this line in the thread (case and spacing aside)."""
    said = " ".join(text.lower().split())
    return any(
        one.actor == actor and " ".join(str(one.arguments.get("text") or "").lower().split()) == said
        for one in thread
    )


async def generate(
    session: PreRunSession,
    listed: dict[str, Actor],
    briefs: dict[str, str],
    write: Write,
) -> PreRunSession:
    """The session with its thread written by its actors, and the fingerprint it was written from. A mocked actor
    writes nothing of its own: only the messages the writer gave it stay. Never raises: an actor whose turn fails
    passes."""
    cap = session.max_messages or LIMIT_DEFAULTS["max_messages"]
    where = session.where or {}
    action = str(where.get("action") or "")
    place = dict(where.get("arguments") or {})
    reply = where.get("reply") or {}
    thread = [
        one
        for one in session.thread
        if (listed.get(one.actor) and listed[one.actor].play == "mocked")
    ]
    writers = [
        listed[one]
        for one in session.actors
        if one in listed and listed[one].play in ("live", "both")
    ]
    while writers and len(thread) < cap:
        wrote = False
        for actor in writers:
            if len(thread) >= cap:
                break
            try:
                raw = write(
                    _brief(actor, briefs.get(actor.id, ""), session, thread), actor
                )
                if inspect.isawaitable(raw):
                    raw = await raw
            except Exception:  # noqa: BLE001 - one actor's failed turn is a pass, never a failed scenario
                continue
            said = _read(raw)
            if not said or not str(said.get("text") or "").strip():
                continue
            if _repeats(actor.id, str(said["text"]).strip(), thread):
                # A line its writer already wrote is a loop: it is not kept, and counts as a pass.
                continue
            answer = said.get("reply_to")
            if (
                isinstance(answer, int)
                and 1 <= answer <= len(thread)
                and reply.get("action")
            ):
                message = ThreadMessage(
                    actor=actor.id,
                    action=str(reply["action"]),
                    arguments={**place, "text": str(said["text"]).strip()},
                    refers={
                        str(reply.get("argument")): Reference(
                            message=answer, field=str(reply.get("field"))
                        )
                    },
                )
            else:
                message = ThreadMessage(
                    actor=actor.id,
                    action=action,
                    arguments={**place, "text": str(said["text"]).strip()},
                )
            thread.append(message)
            wrote = True
        if not wrote:
            break
    return session.model_copy(
        update={"thread": thread, "fingerprint": session_fingerprint(session, listed)}
    )


def stale(session: PreRunSession, listed: dict[str, Actor]) -> bool:
    """Whether a session must be written again before sealing: never written, or written from something else."""
    if session.per_trial:
        return False
    return not session.thread or session.fingerprint != session_fingerprint(
        session, listed
    )


async def written(
    document: dict[str, Any], root: Any, write: Write | None = None
) -> dict[str, Any]:
    """A scenario document whose pre-run sessions are all written: each stale session's thread is generated now by its
    actors (on each actor's model, else the environment's), the rest kept. Called when a scenario is kept or edited."""
    from pathlib import Path

    from .actors import actor_brief, brief_text, load_actors

    sessions = [
        PreRunSession.model_validate(one)
        for one in document.get("pre_run") or []
        if isinstance(one, dict)
    ]
    if not sessions:
        return document
    listing = load_actors(Path(root))
    listed = listing.by_id()
    if not any(stale(one, listed) for one in sessions):
        return document
    briefs = {
        actor_id: brief_text(
            actor_brief(
                listed[actor_id].model_dump(exclude_none=True), scenario=dict(document)
            )
        )
        for session in sessions
        for actor_id in session.actors
        if actor_id in listed
    }
    write = write or _model_writer(listing.limits.model)
    out = []
    for session in sessions:
        out.append(
            await generate(session, listed, briefs, write)
            if stale(session, listed)
            else session
        )
    return {**document, "pre_run": [one.model_dump(mode="json") for one in out]}


def _model_writer(default_model: str | None) -> Write:
    """A session's messages on the one actor decider."""
    from .actor_model import decider

    decide = decider(None, default_model)
    return lambda brief, actor: decide(brief, actor.id, actor.model)


async def refresh_stale(authoring: Any, write: Write | None = None) -> list[str]:
    """Before sealing: every scenario whose pre-run session is stale (never written, or written from an actor record
    or situation that has since changed) gets that session written again, so nothing stale is ever sealed. Returns the
    scenarios rewritten. A scenario that cannot be read is left for the seal's own checks."""
    from pathlib import Path

    from .actors import load_actors

    root = Path(authoring)
    listed = load_actors(root).by_id()
    rewritten = []
    for path in sorted(root.glob("scenarios/*/scenario.json")):
        try:
            document = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if not isinstance(document, dict) or not document.get("pre_run"):
            continue
        try:
            sessions = [
                PreRunSession.model_validate(one) for one in document["pre_run"]
            ]
        except Exception:  # noqa: BLE001 - an unreadable session is the seal's to refuse
            continue
        if not any(stale(one, listed) for one in sessions):
            continue
        updated = await written(document, root, write)
        path.write_text(
            json.dumps(updated, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
        rewritten.append(path.parent.name)
    return rewritten
